from datetime import datetime, timedelta

class Scheduler:
    def __init__(self) -> None:
        self.appointments = {}  # appointment_id -> {'patient': str, 'doctor': str, 'start': datetime, 'end': datetime, 'cancelled': bool}
        self.next_id = 1
        # Track upcoming appointments per patient for requirement #2
        self.patient_appointments = {}  # patient -> list of appointment_ids that are upcoming (not cancelled and start > now)

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        # Check requirement #2: patient can have at most one upcoming appointment
        if patient in self.patient_appointments:
            # Find any upcoming appointment for this patient (not cancelled and start > now)
            upcoming_count = 0
            for appt_id in self.patient_appointments[patient]:
                appt = self.appointments[appt_id]
                if not appt['cancelled'] and appt['start'] > now:
                    upcoming_count += 1
            if upcoming_count >= 1:
                raise ValueError("Patient already has an upcoming appointment")

        # Check requirement #3: doctor must be free during the requested time
        if not self.is_free(doctor, start, end):
            raise ValueError("Doctor is not available during the requested time")

        # Create new appointment
        appointment_id = self.next_id
        self.next_id += 1

        self.appointments[appointment_id] = {
            'patient': patient,
            'doctor': doctor,
            'start': start,
            'end': end,
            'cancelled': False
        }

        # Add to patient's appointments list
        if patient not in self.patient_appointments:
            self.patient_appointments[patient] = []
        self.patient_appointments[patient].append(appointment_id)

        return appointment_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        if appointment_id not in self.appointments:
            raise ValueError("Appointment does not exist")

        appointment = self.appointments[appointment_id]

        # If appointment is already cancelled, do nothing
        if appointment['cancelled']:
            return

        # Check if cancellation is less than 24 hours before start
        # If so, we still mark it as cancelled but don't free the slot (it stays blocked)
        # So we just set cancelled = True and that's it
        appointment['cancelled'] = True

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        # Check all appointments for this doctor
        for appt_id, appt in self.appointments.items():
            if appt['doctor'] == doctor and not appt['cancelled']:
                # Check for overlap: two intervals [a,b] and [c,d] overlap iff a < d and c < b
                # Since touching is allowed (one ends when another starts), we use strict inequalities
                # So [start, end] overlaps with [appt['start'], appt['end']] iff 
                # start < appt['end'] and appt['start'] < end
                if start < appt['end'] and appt['start'] < end:
                    return False
        return True
